import { useNavigate } from 'react-router-dom';
import { usePsychologyStore, useAssessmentStore, useFinancialPlanStore } from '../../stores';
import { useCurrency } from '../../hooks/useCurrency';

interface ScoreCard {
  title: string;
  score: number | null;
  maxScore: number;
  color: string;
  status: 'Excellent' | 'Good' | 'Needs Work' | 'Not Started';
  recommendation: string;
  action: string;
  route: string;
}

export default function ResultsDashboard() {
  const navigate = useNavigate();
  const { getMindsetScore, stepsCompleted } = usePsychologyStore();
  const { getBlueprintScores } = useAssessmentStore();
  const { financialData } = useFinancialPlanStore();
  const { getSymbol } = useCurrency();
  const currencySymbol = getSymbol();

  const mindsetScore = getMindsetScore();
  const blueprintScores = getBlueprintScores();

  const getScoreStatus = (score: number, maxScore: number) => {
    const percentage = (score / maxScore) * 100;
    if (percentage >= 80) return 'Excellent';
    if (percentage >= 60) return 'Good';
    return 'Needs Work';
  };

  const getScoreColor = (score: number, maxScore: number) => {
    const percentage = (score / maxScore) * 100;
    if (percentage >= 80) return 'text-green-400';
    if (percentage >= 60) return 'text-yellow-400';
    return 'text-red-400';
  };

  const scoreCards: ScoreCard[] = [
    {
      title: 'Mindset & Psychology',
      score: stepsCompleted.includes(2) ? mindsetScore : null,
      maxScore: 100,
      color: getScoreColor(mindsetScore, 100),
      status: stepsCompleted.includes(2) ? getScoreStatus(mindsetScore, 100) : 'Not Started',
      recommendation: stepsCompleted.includes(2) && mindsetScore < 70
        ? 'Your mindset may be limiting your financial potential. Focus on transforming limiting beliefs.'
        : stepsCompleted.includes(2)
        ? 'Strong foundation! Your psychology supports wealth building.'
        : 'Complete the Mindset Assessment to identify your money beliefs.',
      action: stepsCompleted.includes(2) ? 'Review Results' : 'Take Assessment',
      route: stepsCompleted.includes(2) ? '/psychology/results' : '/training/mindset',
    },
    {
      title: 'Psychology Score',
      score: blueprintScores?.psychologyScore || null,
      maxScore: 10,
      color: blueprintScores?.psychologyScore
        ? getScoreColor(blueprintScores.psychologyScore, 10)
        : 'text-gray-400',
      status: blueprintScores?.psychologyScore !== undefined
        ? getScoreStatus(blueprintScores.psychologyScore, 10)
        : 'Not Started',
      recommendation: blueprintScores?.psychologyScore && blueprintScores.psychologyScore < 7
        ? 'Your money beliefs need attention. Start with psychology training.'
        : blueprintScores?.psychologyScore
        ? 'Your money psychology is empowering and supports good decisions.'
        : 'Complete Blueprint Assessment to evaluate your financial psychology.',
      action: blueprintScores?.psychologyScore !== undefined ? 'Review Details' : 'Take Assessment',
      route: blueprintScores?.psychologyScore !== undefined ? '/assessments/blueprint' : '/training/financial',
    },
    {
      title: 'Economics Knowledge',
      score: blueprintScores?.economicsScore || null,
      maxScore: 10,
      color: blueprintScores?.economicsScore
        ? getScoreColor(blueprintScores.economicsScore, 10)
        : 'text-gray-400',
      status: blueprintScores?.economicsScore !== undefined
        ? getScoreStatus(blueprintScores.economicsScore, 10)
        : 'Not Started',
      recommendation: blueprintScores?.economicsScore && blueprintScores.economicsScore < 7
        ? 'Focus on understanding your current financial situation and key concepts.'
        : blueprintScores?.economicsScore
        ? 'Solid financial literacy foundation. Keep building knowledge.'
        : 'Complete Blueprint Assessment to evaluate your financial knowledge.',
      action: blueprintScores?.economicsScore !== undefined ? 'Review Details' : 'Take Assessment',
      route: blueprintScores?.economicsScore !== undefined ? '/assessments/blueprint' : '/training/financial',
    },
    {
      title: 'Investment Sophistication',
      score: blueprintScores?.sophisticationScore || null,
      maxScore: 10,
      color: blueprintScores?.sophisticationScore
        ? getScoreColor(blueprintScores.sophisticationScore, 10)
        : 'text-gray-400',
      status: blueprintScores?.sophisticationScore !== undefined
        ? getScoreStatus(blueprintScores.sophisticationScore, 10)
        : 'Not Started',
      recommendation: blueprintScores?.sophisticationScore && blueprintScores.sophisticationScore < 7
        ? 'Learn about diversified investing, asset allocation, and long-term strategies.'
        : blueprintScores?.sophisticationScore
        ? 'Your investment approach is sophisticated and well-diversified.'
        : 'Complete Blueprint Assessment to evaluate your investment sophistication.',
      action: blueprintScores?.sophisticationScore !== undefined ? 'Review Details' : 'Take Assessment',
      route: blueprintScores?.sophisticationScore !== undefined ? '/assessments/blueprint' : '/training/financial',
    },
    {
      title: 'Action & Execution',
      score: blueprintScores?.executionScore || null,
      maxScore: 10,
      color: blueprintScores?.executionScore
        ? getScoreColor(blueprintScores.executionScore, 10)
        : 'text-gray-400',
      status: blueprintScores?.executionScore !== undefined
        ? getScoreStatus(blueprintScores.executionScore, 10)
        : 'Not Started',
      recommendation: blueprintScores?.executionScore && blueprintScores.executionScore < 7
        ? 'Set up automatic savings and investment systems. Focus on consistency.'
        : blueprintScores?.executionScore
        ? 'Excellent execution habits. You consistently apply financial knowledge.'
        : 'Complete Blueprint Assessment to evaluate your action-taking habits.',
      action: blueprintScores?.executionScore !== undefined ? 'Review Details' : 'Take Assessment',
      route: blueprintScores?.executionScore !== undefined ? '/assessments/blueprint' : '/training/financial',
    },
  ];

  // Prioritize what needs work
  const needsWork = scoreCards.filter(
    (card) => card.score !== null && card.status === 'Needs Work'
  ).sort((a, b) => (a.score! / a.maxScore) - (b.score! / b.maxScore));

  const notStarted = scoreCards.filter((card) => card.status === 'Not Started');

  const completedCount = scoreCards.filter((card) => card.score !== null).length;
  const totalCount = scoreCards.length;
  const overallProgress = Math.round((completedCount / totalCount) * 100);

  return (
    <div className="min-h-screen bg-gradient-to-br from-dark-bg to-dark-surface py-12 px-4">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="text-center mb-12">
          <h1 className="text-5xl font-bold text-white mb-4">
            Your Financial Blueprint
          </h1>
          <p className="text-xl text-gray-300 mb-2">
            Comprehensive results and personalized recommendations
          </p>
          <div className="flex items-center justify-center gap-3">
            <div className="w-full max-w-md bg-dark-bg rounded-full h-3">
              <div
                className="bg-primary-teal h-3 rounded-full transition-all"
                style={{ width: `${overallProgress}%` }}
              />
            </div>
            <span className="text-primary-teal font-semibold">{overallProgress}% Complete</span>
          </div>
        </div>

        {/* Priority Section - What Needs Work */}
        {needsWork.length > 0 && (
          <div className="bg-gradient-to-r from-red-400/10 to-orange-400/10 border border-red-400/30 rounded-lg p-6 mb-8">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-12 h-12 bg-red-400/20 rounded-full flex items-center justify-center">
                <span className="text-2xl">🎯</span>
              </div>
              <div>
                <h2 className="text-2xl font-bold text-white">Priority Areas</h2>
                <p className="text-gray-400 text-sm">Focus here first for biggest impact</p>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {needsWork.map((card, index) => (
                <div key={index} className="bg-dark-bg/50 border border-dark-border rounded-lg p-4">
                  <div className="flex justify-between items-start mb-2">
                    <h3 className="text-lg font-semibold text-white">{card.title}</h3>
                    {card.score !== null && (
                      <span className={`text-xl font-bold ${card.color}`}>
                        {card.score}/{card.maxScore}
                      </span>
                    )}
                  </div>
                  <p className="text-gray-400 text-sm mb-3">{card.recommendation}</p>
                  <button
                    onClick={() => navigate(card.route)}
                    className="text-primary-teal hover:text-teal-300 text-sm font-semibold underline"
                  >
                    {card.action} →
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Not Started Section */}
        {notStarted.length > 0 && (
          <div className="bg-dark-surface border border-dark-border rounded-lg p-6 mb-8">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-12 h-12 bg-gray-400/20 rounded-full flex items-center justify-center">
                <span className="text-2xl">📝</span>
              </div>
              <div>
                <h2 className="text-2xl font-bold text-white">Not Started</h2>
                <p className="text-gray-400 text-sm">Complete these to get your full picture</p>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {notStarted.map((card, index) => (
                <button
                  key={index}
                  onClick={() => navigate(card.route)}
                  className="bg-dark-bg border border-dark-border hover:border-primary-teal rounded-lg p-4 text-left transition-colors"
                >
                  <h3 className="text-lg font-semibold text-white mb-1">{card.title}</h3>
                  <p className="text-primary-teal text-sm font-semibold">
                    {card.action} →
                  </p>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* All Score Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
          {scoreCards.map((card, index) => (
            <div
              key={index}
              className={`bg-dark-surface border-2 rounded-lg p-6 transition-all ${
                card.status === 'Needs Work'
                  ? 'border-red-400/50'
                  : card.status === 'Excellent'
                  ? 'border-green-400/50'
                  : 'border-dark-border'
              }`}
            >
              <div className="flex justify-between items-start mb-4">
                <div>
                  <h3 className="text-xl font-bold text-white mb-1">{card.title}</h3>
                  <span className={`text-sm font-semibold ${
                    card.status === 'Excellent'
                      ? 'text-green-400'
                      : card.status === 'Good'
                      ? 'text-yellow-400'
                      : card.status === 'Needs Work'
                      ? 'text-red-400'
                      : 'text-gray-400'
                  }`}>
                    {card.status}
                  </span>
                </div>
                {card.score !== null && (
                  <div className={`text-4xl font-bold ${card.color}`}>
                    {card.score}
                    <span className="text-lg text-gray-400">/{card.maxScore}</span>
                  </div>
                )}
              </div>

              <p className="text-gray-400 text-sm mb-4 leading-relaxed">
                {card.recommendation}
              </p>

              <button
                onClick={() => navigate(card.route)}
                className="w-full px-4 py-2 rounded-lg bg-primary-teal/10 border border-primary-teal text-primary-teal hover:bg-primary-teal hover:text-white transition-colors text-sm font-semibold"
              >
                {card.action} →
              </button>
            </div>
          ))}
        </div>

        {/* Financial Plan Summary */}
        {financialData && (
          <div className="bg-gradient-to-r from-primary-pink/20 to-primary-purple/20 border border-primary-pink/30 rounded-lg p-6 mb-8">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-12 h-12 bg-primary-pink rounded-full flex items-center justify-center">
                <span className="text-2xl">💰</span>
              </div>
              <div>
                <h2 className="text-2xl font-bold text-white">Financial Plan Complete!</h2>
                <p className="text-gray-400 text-sm">Your personalized wealth plan is ready</p>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="bg-dark-bg/50 rounded-lg p-4">
                <p className="text-gray-400 text-sm mb-1">Annual Income</p>
                <p className="text-xl font-bold text-white">
                  {currencySymbol}{financialData.annualIncome?.toLocaleString()}
                </p>
              </div>
              <div className="bg-dark-bg/50 rounded-lg p-4">
                <p className="text-gray-400 text-sm mb-1">Savings Rate</p>
                <p className="text-xl font-bold text-white">
                  {(financialData.savingsRate * 100).toFixed(0)}%
                </p>
              </div>
              <div className="bg-dark-bg/50 rounded-lg p-4">
                <p className="text-gray-400 text-sm mb-1">Net Worth</p>
                <p className="text-xl font-bold text-white">
                  {currencySymbol}{(() => {
                    const totalAssets = financialData.assets.reduce((sum, asset) => sum + asset.value, 0);
                    const totalLiabilities = financialData.liabilities.reduce((sum, liability) => sum + liability.balance, 0);
                    return (totalAssets - totalLiabilities).toLocaleString();
                  })()}
                </p>
              </div>
            </div>
            <button
              onClick={() => navigate('/planning/generate')}
              className="mt-4 w-full px-4 py-2 rounded-lg bg-primary-pink hover:bg-pink-600 text-white font-semibold transition-colors"
            >
              View Financial Plan →
            </button>
          </div>
        )}

        {/* Bottom Actions */}
        <div className="bg-dark-surface border border-dark-border rounded-lg p-6">
          <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
            <p className="text-gray-300">
              {completedCount === totalCount
                ? 'All assessments complete! Review your results and continue building your financial future.'
                : `${totalCount - completedCount} assessment${totalCount - completedCount > 1 ? 's' : ''} remaining to complete your financial blueprint.`}
            </p>
            <div className="flex gap-3">
              <button
                onClick={() => navigate('/training/hub')}
                className="px-6 py-3 rounded-lg border border-dark-border text-gray-300 hover:border-gray-500 hover:text-white transition-colors font-semibold"
              >
                Training Hub
              </button>
              {completedCount === totalCount && (
                <button
                  onClick={() => navigate('/planning/generate')}
                  className="px-6 py-3 rounded-lg bg-primary-teal hover:bg-teal-600 text-white font-semibold transition-colors"
                >
                  View Financial Plan →
                </button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
